package ch.bbw.zork;/** * author: Camilla Della Santa, Version:1.0, 28 October 2026 */import java.util.Arrays;import java.util.List;/** * All the command words to play. */public class CommandWords {	private List<String> validCommands = Arrays.asList(			"go", "back","take", "drop", "inventory", "map", "quit", "help" );	/**	 * @param commandWord the word typed by the player	 * @return true if this is a valid command word	 */	public boolean isCommand(String commandWord) {		return validCommands.contains(commandWord);	}	/** @return all valid command words separated by a space */	public String showAll() {		return String.join(" ", validCommands);	}}